    def ip_to_int(ip):
        octets = [int(x) for x in ip.split('.')]
        return (octets[0] << 24) | (octets[1] << 16) | (octets[2] << 8) | octets[3]

    def int_to_ip(n):
        return f"{(n >> 24) & 255}.{(n >> 16) & 255}.{(n >> 8) & 255}.{n & 255}"

    if not blocks:
        return []

    intervals = []
    for b in blocks:
        ip_str, p_str = b.split('/')
        p = int(p_str)
        ip = ip_to_int(ip_str)
        mask = (0xFFFFFFFF << (32 - p)) & 0xFFFFFFFF if p > 0 else 0
        start = ip & mask
        end = start + (0xFFFFFFFF >> p) if p < 32 else start
        intervals.append((start, end))

    intervals.sort()
    merged = []
    if intervals:
        curr_start, curr_end = intervals[0]
        for next_start, next_end in intervals[1:]:
            if next_start <= curr_end + 1:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))

    def get_cidrs(start, end):
        results = []
        while start <= end:
            p = 32
            while p > 0:
                mask = (0xFFFFFFFF << (32 - (p - 1))) & 0xFFFFFFFF if p - 1 > 0 else 0
                if (start & ~mask) == 0 and start + (0xFFFFFFFF >> (p - 1)) <= end:
                    p -= 1
                else:
                    break
            results.append(f"{int_to_ip(start)}/{p}")
            start += (0xFFFFFFFF >> p) + 1
        return results

    final = []
    for s, e in merged:
        final.extend(get_cidrs(s, e))
    return final

